# Check the later correction listings. Does not rewrite listing-bytes-r1.txt.
# Do not edit this file after it has run.
import re
from pathlib import Path

BASE = 0x60021020
img = Path('inputs/00_0100_50000020.decoded.bin').read_bytes()
pat = re.compile(r'^([0-9a-fA-F]{8})\t([0-9a-fA-F]+)\t')
names = [
    'accessor-r1.txt', 'orient-cmp-r1.txt', 'editor-6041a1fb-r1.txt', 'editor-call-r1.txt',
]
out = []
root = Path('work/out/listings')
for name in names:
    path = root / name
    checked = 0
    bad = 0
    samples = []
    for line in path.read_text(encoding='utf-8', errors='replace').splitlines():
        m = pat.match(line)
        if not m:
            continue
        addr = int(m.group(1), 16)
        hx = m.group(2).lower()
        off = addr - BASE
        nbytes = len(hx) // 2
        checked += 1
        if off < 0 or off + nbytes > len(img) or len(hx) % 2 or img[off:off + nbytes].hex() != hx:
            bad += 1
            if len(samples) < 3:
                samples.append('%08x %s' % (addr, hx))
    out.append('%s checked %d mismatches %d' % (name, checked, bad))
    out.extend('  ' + s for s in samples)
text = '\n'.join(out) + '\n'
Path('work/out/listing-bytes-r1b.txt').write_text(text, encoding='utf-8')
print(text)
